package com.iare.club.controller;
import com.iare.club.entity.*;import com.iare.club.repository.*;import com.iare.club.service.*;import org.springframework.data.domain.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/admin") public class AdminFinanceController{
 private final DepositRepository deposits;private final WithdrawalRepository withdrawalRepo;private final WithdrawalService withdrawals;
 public AdminFinanceController(DepositRepository d,WithdrawalRepository wr,WithdrawalService ws){deposits=d;withdrawalRepo=wr;withdrawals=ws;}
 @GetMapping("/deposits") String deposits(@RequestParam(defaultValue="")String q,@RequestParam(required=false)Deposit.Status status,@RequestParam(defaultValue="0")int page,Model model){Page<Deposit> result=deposits.search(status,q.strip(),PageRequest.of(Math.max(0,page),15));model.addAttribute("page",result);model.addAttribute("q",q);model.addAttribute("selectedStatus",status);model.addAttribute("statuses",Deposit.Status.values());model.addAttribute("pendingCount",deposits.countByStatus(Deposit.Status.PENDING));model.addAttribute("successfulCount",deposits.countByStatus(Deposit.Status.SUCCESSFUL));model.addAttribute("failedCount",deposits.countByStatus(Deposit.Status.FAILED)+deposits.countByStatus(Deposit.Status.CANCELLED));return "admin/deposits";}
 @GetMapping("/deposits/{id}") String depositDetail(@PathVariable long id,Model model){model.addAttribute("deposit",deposits.findDetailById(id).orElseThrow());return "admin/deposit-view";}
 @GetMapping("/withdrawals") String withdrawals(@RequestParam(defaultValue="")String q,@RequestParam(required=false)WithdrawalRequest.Status status,@RequestParam(defaultValue="0")int page,Model model){Page<WithdrawalRequest> result=withdrawalRepo.search(status,q.strip(),PageRequest.of(Math.max(0,page),15));model.addAttribute("page",result);model.addAttribute("q",q);model.addAttribute("selectedStatus",status);model.addAttribute("statuses",WithdrawalRequest.Status.values());model.addAttribute("pendingCount",withdrawalRepo.countByStatus(WithdrawalRequest.Status.PENDING));model.addAttribute("processingCount",withdrawalRepo.countByStatus(WithdrawalRequest.Status.PROCESSING));model.addAttribute("successfulCount",withdrawalRepo.countByStatus(WithdrawalRequest.Status.SUCCESSFUL));return "admin/withdrawals";}
 @GetMapping("/withdrawals/{id}") String withdrawalDetail(@PathVariable long id,Model model){WithdrawalRequest request=withdrawalRepo.findDetailById(id).orElseThrow();model.addAttribute("withdrawal",request);model.addAttribute("fullAccountNumber",withdrawals.fullAccountNumber(request.getBankAccount()));model.addAttribute("ifsc",withdrawals.ifsc(request.getBankAccount()));model.addAttribute("statuses",WithdrawalRequest.Status.values());return "admin/withdrawal-view";}
 @PostMapping("/withdrawals/{id}/status") String updateWithdrawal(@PathVariable long id,@RequestParam WithdrawalRequest.Status status,@RequestParam String remarks,@RequestParam(required=false)String payoutReference,Authentication auth,RedirectAttributes flash){try{withdrawals.transition(id,status,remarks,payoutReference,auth.getName());flash.addFlashAttribute("success",status==WithdrawalRequest.Status.SUCCESSFUL?"Withdrawal marked Successful. The verified bank payout was recorded and reserved funds were finalized.":"Withdrawal status updated and audit log recorded.");}catch(RuntimeException e){flash.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/withdrawals/"+id;}
}
